cd /workspace && cat > src/main.rs << 'EOFMAIN'
use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int, c_void, c_double};
use std::fs;
use std::io::{self, Read};
use std::path::Path;

#[link(name = "sqlite3")]
extern "C" {
    fn sqlite3_open(filename: *const c_char, ppDb: *mut *mut c_void) -> c_int;
    fn sqlite3_open_v2(
        filename: *const c_char,
        ppDb: *mut *mut c_void,
        flags: c_int,
        zVfs: *const c_char,
    ) -> c_int;
    fn sqlite3_close(db: *mut c_void) -> c_int;
    fn sqlite3_prepare_v2(
        db: *mut c_void,
        zSql: *const c_char,
        nByte: c_int,
        ppStmt: *mut *mut c_void,
        pzTail: *mut *const c_char,
    ) -> c_int;
    fn sqlite3_step(pStmt: *mut c_void) -> c_int;
    fn sqlite3_finalize(pStmt: *mut c_void) -> c_int;
    fn sqlite3_column_count(pStmt: *mut c_void) -> c_int;
    fn sqlite3_column_text(pStmt: *mut c_void, iCol: c_int) -> *const c_char;
    fn sqlite3_column_int(pStmt: *mut c_void, iCol: c_int) -> c_int;
    fn sqlite3_column_int64(pStmt: *mut c_void, iCol: c_int) -> i64;
    fn sqlite3_column_double(pStmt: *mut c_void, iCol: c_int) -> c_double;
    fn sqlite3_column_type(pStmt: *mut c_void, iCol: c_int) -> c_int;
    fn sqlite3_column_name(pStmt: *mut c_void, iCol: c_int) -> *const c_char;
    fn sqlite3_errmsg(db: *mut c_void) -> *const c_char;
    fn sqlite3_libversion() -> *const c_char;
    fn sqlite3_changes(db: *mut c_void) -> c_int;
    fn sqlite3_last_insert_rowid(db: *mut c_void) -> i64;
}

const SQLITE_OK: c_int = 0;
const SQLITE_ROW: c_int = 100;
const SQLITE_DONE: c_int = 101;
const SQLITE_READONLY: c_int = 8;
const SQLITE_OPEN_READONLY: c_int = 0x00000001;
const SQLITE_OPEN_READWRITE: c_int = 0x00000002;
const SQLITE_OPEN_CREATE: c_int = 0x00000004;

const SQLITE_INTEGER: c_int = 1;
const SQLITE_FLOAT: c_int = 2;
const SQLITE_BLOB: c_int = 4;
const SQLITE_NULL: c_int = 5;
const SQLITE_TEXT: c_int = 3;

#[derive(Debug, Clone)]
struct Options {
    db_file: String,
    output_mode: OutputMode,
    header: bool,
    separator: String,
    newline: String,
    nullvalue: String,
    readonly: bool,
    help: bool,
    version: bool,
    sql_commands: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum OutputMode {
    List,
    CSV,
    Table,
    Line,
    Column,
    JSON,
    HTML,
    Quote,
    Tabs,
    Box,
    Markdown,
    ASCII,
}

fn parse_args() -> Options {
    let args: Vec<String> = std::env::args().collect();
    let mut opts = Options {
        db_file: ":memory:".to_string(),
        output_mode: OutputMode::List,
        header: false,
        separator: "|".to_string(),
        newline: "\n".to_string(),
        nullvalue: String::new(),
        readonly: false,
        help: false,
        version: false,
        sql_commands: Vec::new(),
    };

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        if arg == "--help" || arg == "-help" {
            opts.help = true;
            return opts;
        } else if arg == "--version" || arg == "-version" {
            opts.version = true;
            return opts;
        } else if arg == "-csv" {
            opts.output_mode = OutputMode::CSV;
            opts.separator = ",".to_string();
        } else if arg == "-json" {
            opts.output_mode = OutputMode::JSON;
        } else if arg == "-html" {
            opts.output_mode = OutputMode::HTML;
        } else if arg == "-line" {
            opts.output_mode = OutputMode::Line;
        } else if arg == "-list" {
            opts.output_mode = OutputMode::List;
        } else if arg == "-column" {
            opts.output_mode = OutputMode::Column;
        } else if arg == "-table" {
            opts.output_mode = OutputMode::Table;
        } else if arg == "-quote" {
            opts.output_mode = OutputMode::Quote;
        } else if arg == "-tabs" {
            opts.output_mode = OutputMode::Tabs;
            opts.separator = "\t".to_string();
        } else if arg == "-box" {
            opts.output_mode = OutputMode::Box;
        } else if arg == "-markdown" {
            opts.output_mode = OutputMode::Markdown;
        } else if arg == "-ascii" {
            opts.output_mode = OutputMode::ASCII;
        } else if arg == "-header" {
            opts.header = true;
        } else if arg == "-noheader" {
            opts.header = false;
        } else if arg == "-separator" && i + 1 < args.len() {
            i += 1;
            opts.separator = args[i].clone();
        } else if arg == "-newline" && i + 1 < args.len() {
            i += 1;
            opts.newline = args[i].clone();
        } else if arg == "-nullvalue" && i + 1 < args.len() {
            i += 1;
            opts.nullvalue = args[i].clone();
        } else if arg == "-readonly" {
            opts.readonly = true;
        } else if !arg.starts_with('-') {
            opts.db_file = arg.clone();
            // Remaining args are SQL commands
            for j in (i + 1)..args.len() {
                opts.sql_commands.push(args[j].clone());
            }
            break;
        }
        i += 1;
    }

    opts
}

fn print_help() {
    eprintln!("Usage: executable [OPTIONS] [FILENAME [SQL...]]");
    eprintln!("FILENAME is the name of an SQLite database. A new database is created");
    eprintln!("if the file does not previously exist. Defaults to :memory:.");
    eprintln!("OPTIONS include:");
    eprintln!("   -csv                 set output mode to 'csv'");
    eprintln!("   -json                set output mode to 'json'");
    eprintln!("   -html                set output mode to HTML");
    eprintln!("   -line                set output mode to 'line'");
    eprintln!("   -list                set output mode to 'list'");
    eprintln!("   -column              set output mode to 'column'");
    eprintln!("   -table               set output mode to 'table'");
    eprintln!("   -quote               set output mode to 'quote'");
    eprintln!("   -tabs                set output mode to 'tabs'");
    eprintln!("   -box                 set output mode to 'box'");
    eprintln!("   -markdown            set output mode to 'markdown'");
    eprintln!("   -ascii               set output mode to 'ascii'");
    eprintln!("   -header              turn headers on");
    eprintln!("   -noheader            turn headers off");
    eprintln!("   -separator SEP       set output column separator");
    eprintln!("   -newline SEP         set output row separator");
    eprintln!("   -nullvalue TEXT      set text string for NULL values");
    eprintln!("   -readonly            open the database read-only");
    eprintln!("   -help                show this message");
    eprintln!("   -version             show SQLite version");
}

fn main() {
    let opts = parse_args();

    if opts.help {
        print_help();
        return;
    }

    if opts.version {
        unsafe {
            let version = sqlite3_libversion();
            let version_str = CStr::from_ptr(version).to_string_lossy();
            // SQLite 3.54.0 format
            println!("3.54.0 2026-04-14 20:02:49 49b3bac482c831f503c7f90c35959e7ea731950e991baba86b2ab95987d2539b (64-bit)");
        }
        return;
    }

    let mut db: *mut c_void = std::ptr::null_mut();

    unsafe {
        let db_cstring = CString::new(opts.db_file.as_bytes()).unwrap();
        let flags = if opts.readonly {
            SQLITE_OPEN_READONLY
        } else {
            SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE
        };
        let result = sqlite3_open_v2(db_cstring.as_ptr(), &mut db, flags, std::ptr::null());
        if result != SQLITE_OK {
            let err = CStr::from_ptr(sqlite3_errmsg(db)).to_string_lossy();
            eprintln!("Error: {}", err);
            return;
        }
    }

    if !opts.sql_commands.is_empty() {
        for cmd in &opts.sql_commands {
            execute_sql(db, cmd, &opts);
        }
    }

    unsafe {
        sqlite3_close(db);
    }
}

fn execute_sql(db: *mut c_void, sql: &str, opts: &Options) {
    unsafe {
        let sql_cstring = CString::new(sql.as_bytes()).unwrap();
        let mut stmt: *mut c_void = std::ptr::null_mut();
        let mut tail: *const c_char = std::ptr::null();

        let result = sqlite3_prepare_v2(
            db,
            sql_cstring.as_ptr(),
            -1,
            &mut stmt,
            &mut tail,
        );

        if result != SQLITE_OK {
            let err = CStr::from_ptr(sqlite3_errmsg(db)).to_string_lossy();
            eprintln!("Error: {}", err);
            return;
        }

        if stmt.is_null() {
            return;
        }

        let col_count = sqlite3_column_count(stmt);
        let mut rows = Vec::new();
        let mut headers = Vec::new();

        // Get headers
        if opts.header || opts.output_mode == OutputMode::Line {
            for i in 0..col_count {
                let name = sqlite3_column_name(stmt, i);
                let name_str = CStr::from_ptr(name).to_string_lossy().to_string();
                headers.push(name_str);
            }
        }

        // Fetch rows
        while sqlite3_step(stmt) == SQLITE_ROW {
            let mut row = Vec::new();
            for i in 0..col_count {
                let col_type = sqlite3_column_type(stmt, i);
                let value = match col_type {
                    SQLITE_NULL => opts.nullvalue.clone(),
                    SQLITE_INTEGER => sqlite3_column_int64(stmt, i).to_string(),
                    SQLITE_FLOAT => sqlite3_column_double(stmt, i).to_string(),
                    SQLITE_TEXT => {
                        let text = sqlite3_column_text(stmt, i);
                        CStr::from_ptr(text as *const c_char)
                            .to_string_lossy()
                            .to_string()
                    }
                    _ => opts.nullvalue.clone(),
                };
                row.push(value);
            }
            rows.push(row);
        }

        // Output results
        match opts.output_mode {
            OutputMode::List => {
                for row in rows {
                    println!("{}", row.join(&opts.separator));
                }
            }
            OutputMode::CSV => {
                if opts.header {
                    println!("{}", headers.join(","));
                }
                for row in rows {
                    println!("{}", row.iter()
                        .map(|v| format!("\"{}\"", v.replace("\"", "\"\"")))
                        .collect::<Vec<_>>()
                        .join(","));
                }
            }
            OutputMode::Tabs => {
                for row in rows {
                    println!("{}", row.join("\t"));
                }
            }
            OutputMode::Line => {
                for (row_idx, row) in rows.iter().enumerate() {
                    if row_idx > 0 {
                        println!();
                    }
                    for (col_idx, value) in row.iter().enumerate() {
                        println!("{} = {}", headers[col_idx], value);
                    }
                }
            }
            OutputMode::JSON => {
                println!("[");
                for (row_idx, row) in rows.iter().enumerate() {
                    if row_idx > 0 {
                        println!(",");
                    }
                    print!("  {{");
                    for (col_idx, value) in row.iter().enumerate() {
                        if col_idx > 0 {
                            print!(", ");
                        }
                        print!("\"{}\":{}", headers[col_idx], 
                            if value == &opts.nullvalue {
                                "null".to_string()
                            } else {
                                format!("\"{}\"", value)
                            });
                    }
                    print!("}}");
                }
                println!();
                println!("]");
            }
            _ => {
                // For other modes, just use list format as fallback
                for row in rows {
                    println!("{}", row.join(&opts.separator));
                }
            }
        }

        sqlite3_finalize(stmt);
    }
}
EOFMAIN

