            return opts;
        } else if arg == "--version" || arg == "-version" {
            opts.version = true;
            return opts;
        } else if arg == "-csv" {
            opts.output_mode = OutputMode::CSV;
            opts.separator = ",".to_string();
        } else if arg == "-json" {
            opts.output_mode = OutputMode::JSON;
        } else if arg == "-html" {
            opts.output_mode = OutputMode::HTML;
        } else if arg == "-line" {
            opts.output_mode = OutputMode::Line;
        } else if arg == "-list" {
            opts.output_mode = OutputMode::List;
        } else if arg == "-column" {
            opts.output_mode = OutputMode::Column;
        } else if arg == "-table" {
            opts.output_mode = OutputMode::Table;
        } else if arg == "-quote" {
            opts.output_mode = OutputMode::Quote;
        } else if arg == "-tabs" {
            opts.output_mode = OutputMode::Tabs;
            opts.separator = "\t".to_string();
        } else if arg == "-box" {
            opts.output_mode = OutputMode::Box;
        } else if arg == "-markdown" {
            opts.output_mode = OutputMode::Markdown;
