            opts.output_mode = OutputMode::ASCII;
        } else if arg == "-header" {
            opts.header = true;
        } else if arg == "-noheader" {
            opts.header = false;
        } else if arg == "-separator" && i + 1 < args.len() {
            i += 1;
            opts.separator = args[i].clone();
        } else if arg == "-newline" && i + 1 < args.len() {
            i += 1;
            opts.newline = args[i].clone();
        } else if arg == "-nullvalue" && i + 1 < args.len() {
            i += 1;
            opts.nullvalue = args[i].clone();
        } else if arg == "-readonly" {
            opts.readonly = true;
        } else if !arg.starts_with('-') {
            opts.db_file = arg.clone();
            // Remaining args are SQL commands
            for j in (i + 1)..args.len() {
