            let version_str = CStr::from_ptr(version).to_string_lossy();
            // SQLite 3.54.0 format
            println!("3.54.0 2026-04-14 20:02:49 49b3bac482c831f503c7f90c35959e7ea731950e991baba86b2ab95987d2539b (64-bit)");
        }
        return;
    }

    let mut db: *mut c_void = std::ptr::null_mut();

    unsafe {
        let db_cstring = CString::new(opts.db_file.as_bytes()).unwrap();
        let flags = if opts.readonly {
            SQLITE_OPEN_READONLY
        } else {
            SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE
        };
        let result = sqlite3_open_v2(db_cstring.as_ptr(), &mut db, flags, std::ptr::null());
        if result != SQLITE_OK {
            let err = CStr::from_ptr(sqlite3_errmsg(db)).to_string_lossy();
            eprintln!("Error: {}", err);
            return;
        }
    }

    if !opts.sql_commands.is_empty() {
