fn execute_sql(db: *mut c_void, sql: &str, opts: &Options) {
    unsafe {
        let sql_cstring = CString::new(sql.as_bytes()).unwrap();
        let mut stmt: *mut c_void = std::ptr::null_mut();
        let mut tail: *const c_char = std::ptr::null();

        let result = sqlite3_prepare_v2(
            db,
            sql_cstring.as_ptr(),
            -1,
            &mut stmt,
            &mut tail,
        );

        if result != SQLITE_OK {
            let err = CStr::from_ptr(sqlite3_errmsg(db)).to_string_lossy();
            eprintln!("Error: {}", err);
            return;
        }

        if stmt.is_null() {
            return;
        }

        let col_count = sqlite3_column_count(stmt);
        let mut rows = Vec::new();
        let mut headers = Vec::new();

        // Get headers
        if opts.header || opts.output_mode == OutputMode::Line {
            for i in 0..col_count {
                let name = sqlite3_column_name(stmt, i);
                let name_str = CStr::from_ptr(name).to_string_lossy().to_string();
                headers.push(name_str);
            }
        }

        // Fetch rows
        while sqlite3_step(stmt) == SQLITE_ROW {
            let mut row = Vec::new();
            for i in 0..col_count {
                let col_type = sqlite3_column_type(stmt, i);
                let value = match col_type {
                    SQLITE_NULL => opts.nullvalue.clone(),
                    SQLITE_INTEGER => sqlite3_column_int64(stmt, i).to_string(),
                    SQLITE_FLOAT => sqlite3_column_double(stmt, i).to_string(),
                    SQLITE_TEXT => {
                        let text = sqlite3_column_text(stmt, i);
                        CStr::from_ptr(text as *const c_char)
                            .to_string_lossy()
                            .to_string()
                    }
                    _ => opts.nullvalue.clone(),
                };
                row.push(value);
            }
            rows.push(row);
        }

        // Output results
        match opts.output_mode {
            OutputMode::List => {
                for row in rows {
                    println!("{}", row.join(&opts.separator));
                }
            }
            OutputMode::CSV => {
                if opts.header {
                    println!("{}", headers.join(","));
                }
                for row in rows {
                    println!("{}", row.iter()
                        .map(|v| format!("\"{}\"", v.replace("\"", "\"\"")))
                        .collect::<Vec<_>>()
                        .join(","));
                }
            }
            OutputMode::Tabs => {
                for row in rows {
                    println!("{}", row.join("\t"));
                }
            }
            OutputMode::Line => {
                for (row_idx, row) in rows.iter().enumerate() {
                    if row_idx > 0 {
                        println!();
                    }
                    for (col_idx, value) in row.iter().enumerate() {
                        println!("{} = {}", headers[col_idx], value);
                    }
                }
            }
            OutputMode::JSON => {
                println!("[");
                for (row_idx, row) in rows.iter().enumerate() {
                    if row_idx > 0 {
                        println!(",");
                    }
                    print!("  {{");
                    for (col_idx, value) in row.iter().enumerate() {
                        if col_idx > 0 {
                            print!(", ");
                        }
                        print!("\"{}\":{}", headers[col_idx], 
                            if value == &opts.nullvalue {
                                "null".to_string()
                            } else {
                                format!("\"{}\"", value)
                            });
                    }
                    print!("}}");
                }
                println!();
                println!("]");
            }
            _ => {
                // For other modes, just use list format as fallback
                for row in rows {
                    println!("{}", row.join(&opts.separator));
                }
            }
        }

        sqlite3_finalize(stmt);
    }
}
